import{_ as o,o as d,c as a,a2 as c}from"./chunks/framework.DTwTvi8b.js";const u=JSON.parse('{"title":"0022 分阶段执行：研发阶段、闸口、测试验证阶段","description":"","frontmatter":{"editLink":false},"headers":[],"relativePath":"reference/adr/0022-develop-and-verify-phases.md","filePath":"reference/adr/0022-develop-and-verify-phases.md","lastUpdated":null}'),i={name:"reference/adr/0022-develop-and-verify-phases.md"};function t(r,e,l,s,n,h){return d(),a("div",null,[...e[0]||(e[0]=[c('<div><h1 id="_0022-分阶段执行-研发阶段、闸口、测试验证阶段" tabindex="-1">0022 分阶段执行：研发阶段、闸口、测试验证阶段 <a class="header-anchor" href="#_0022-分阶段执行-研发阶段、闸口、测试验证阶段" aria-label="Permalink to &quot;0022 分阶段执行：研发阶段、闸口、测试验证阶段&quot;">​</a></h1><ul><li>状态：已采纳（补充 <a href="./0015-incremental-continue">0015</a>、<a href="./0018-own-worktree-option">0018</a>：测试阶段可以由同一仓库另一个工作区的对话接手）</li></ul><h2 id="背景" tabindex="-1">背景 <a class="header-anchor" href="#背景" aria-label="Permalink to &quot;背景&quot;">​</a></h2><p>原来第 3–11 步一口气跑完，只在方案审核需要需求方决定时停下。很多团队的研发和测试是两拨人、两个节奏：研发完成要&quot;提测&quot;，测试同事先部署测试环境、准备数据，再验证，或者干脆人工测试；验证也可能想用另一个模型，在另一个时间进行。</p><p>代码评审通过之后、服务启动和功能验证之前，是天然的分界。</p><h2 id="决定" tabindex="-1">决定 <a class="header-anchor" href="#决定" aria-label="Permalink to &quot;决定&quot;">​</a></h2><ul><li>分成固定的两个阶段：<strong>研发</strong>（方案设计 → 方案审核 ⇄ 修订 → 实现 → 代码评审 ⇄ 修复 → 提测说明）和<strong>测试验证</strong>（服务启动 → 功能验证 → 缺陷处理），中间一个闸口。不做任意切分、可配置的阶段：常见的交接点只有&quot;提测&quot;一处，任意切分会让状态、继续规则和手册都变复杂。阶段名在状态里用字符串（<code>develop</code>、<code>verify</code>），以后增加阶段不用改格式。</li><li>研发阶段最后新增一步&quot;提测说明&quot;（builder，<code>handoff.md</code>）。三种执行方式都写：连续时它是功能验证的输入，分阶段时是交给测试的单据，只做研发时是人工测试的依据。</li><li>闸口怎么走由<strong>执行方式</strong>决定，来源后者覆盖前者：配置 <code>phases.mode</code> → spec 头部 <code>- 执行方式：</code> → 启动参数 <code>--phases</code>。 <ul><li><code>continuous</code>（连续，默认）：直接进入测试验证，与之前的行为一致。</li><li><code>gated</code>（分阶段）：状态变为 <code>phase_done</code>，进程正常退出、不占排队名额；通知对话&quot;研发完成，可以提测&quot;，外部通知新事件 <code>phase_done</code>；等待提醒（<code>waitingReminderHours</code>）也覆盖这个状态。<code>--resume --phase verify</code>（或在闸口单独的 <code>--resume</code>）开始测试验证，沿用研发阶段的结果。<code>--verify-at</code> 在研发完成时预约开始时间（复用 <a href="./0020-scheduling-through-the-chat">0020</a> 的定时任务）；研发完成时时间已过就直接继续。</li><li><code>develop-only</code>（只做研发）：写完提测说明后写一份研发报告并结束，状态为 <code>completed</code>；之后仍可用 <code>--phase verify</code> 让流水线做测试验证。</li></ul></li><li>测试验证阶段的选项写在 <code>phases.verify</code>，开始测试时也可以用参数临时指定： <ul><li><code>environment</code>：<code>local</code>（本地启动服务）或 <code>deployed</code>（对已部署的测试环境验证，需要功能目录中的 <code>test-env.md</code>，没有就拒绝开始；不在本地启动服务）。</li><li><code>agents</code>：测试阶段的步骤（服务启动、功能验证、缺陷修复、复验）可以用单独的 agent，格式同顶层 <code>agents</code>，可用 <code>paseoProfile</code>。完成报告仍用顶层的 builder。</li><li><code>defects</code>：<code>fix</code>（当场修复并复验，原来的做法）、<code>handback</code>（只记录，退回研发阶段：在 <code>changes.md</code> 追加&quot;测试验证退回&quot;一节，开始新的一次尝试，按 <a href="./0015-incremental-continue">0015</a> 从方案设计增量处理，修复经过代码评审、重新写提测说明后再提测；次数上限为档位的缺陷修复轮数）、<code>report</code>（只记录，直接出报告）。</li></ul></li><li>测试阶段开始前需求说明改过：按增量继续的规则回到研发阶段的方案设计。</li><li><strong>测试同事接手</strong>：需求在自动新建的工作区中开发（0018）且研发已完成（或已在测试验证阶段）时，同一仓库任何工作区中的对话都可以开始或继续测试验证；通知转到那个对话，步骤仍放在需求的工作区、挂在那个对话下。研发阶段仍然只能从来源目录的对话操作。不在自动新建工作区中的需求，测试同事需要在同一目录的对话中接手（步骤 agent 使用对话的目录，见 <a href="./0001-step-agents-under-origin-chat">0001</a>）。</li><li>安全边界不变：测试环境只能是测试用途的环境；<code>test-env.md</code> 只写口令在哪里取，不写口令本身；提示词继续禁止连接生产环境、使用生产凭据。</li></ul><h2 id="影响" tabindex="-1">影响 <a class="header-anchor" href="#影响" aria-label="Permalink to &quot;影响&quot;">​</a></h2><ul><li>状态文件只增加可选字段（<code>phases</code>、<code>phase</code>、<code>verifyAt</code>、<code>handbacks</code>、步骤记录的 <code>phase</code>）和状态值 <code>phase_done</code>，格式版本仍为 1。回滚到 1.6 后，旧引擎把 <code>phase_done</code> 当作可以继续的中断，继续时沿用研发结果、直接做验证，可以接受。</li><li>所有运行（包括连续方式）多一个&quot;提测说明&quot;步骤，通常几分钟。</li><li>外部通知按约定只增加了事件类型 <code>phase_done</code> 和字段。</li><li>用时与用量可以按阶段统计（状态、完成报告）。</li></ul></div><p class="source-note">本页由仓库中的 <a href="https://github.com/yiyisf/paseo-req-kit/blob/main/docs/adr/0022-develop-and-verify-phases.md">docs/adr/0022-develop-and-verify-phases.md</a> 生成。<a href="https://github.com/yiyisf/paseo-req-kit/edit/main/docs/adr/0022-develop-and-verify-phases.md">在 GitHub 上编辑</a></p>',2)])])}const f=o(i,[["render",t]]);export{u as __pageData,f as default};
